INSERT INTO `Tool` (`id`, `slug`, `name`, `description`, `category`, `isActive`, `isComingSoon`, `icon`, `order`, `metaTitle`, `metaDesc`, `content`, `usageCount`, `createdAt`, `updatedAt`) VALUES ('tool_5', 'qr-code-generator', 'QR Code Generator', 'Generate custom QR codes for URLs, text, Wi-Fi credentials, and contact cards with custom colors.', 'Image Tools', 1, 0, 'QrCode', 5, 'Free QR Code Generator Online - Create Custom QR Codes | Zoqonyx', 'Create high-resolution QR codes for websites, Wi-Fi passwords, text, and vCards. Customize colors and download in PNG format.', '## High-Resolution Custom QR Code Generator\n\nCreate scannable, crystal-clear QR codes for print marketing, restaurant menus, Wi-Fi sharing, and digital business cards.', 0, NOW(3), NOW(3)) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `content` = VALUES(`content`), `isActive` = VALUES(`isActive`), `isComingSoon` = VALUES(`isComingSoon`);
